fn check_match_at(main: &Vec<i32>, sub: &Vec<i32>, start: usize) -> bool {
    // Precondition (as stated in the problem): start + sub.len() <= main.len()
    // We implement the exact intended meaning: all j in [0, sub.len()) match.
    for j in 0..sub.len() {
        if main[start + j] != sub[j] {
            return false;
        }
    }
    true
}

fn is_sub_array(main: &Vec<i32>, sub: &Vec<i32>) -> bool {
    // Empty sub array is always a contiguous subarray
    if sub.is_empty() {
        return true;
    }
    if sub.len() > main.len() {
        return false;
    }

    // Try every valid starting position k where sub could fit in main
    let last_start = main.len() - sub.len();
    for start in 0..=last_start {
        if check_match_at(main, sub, start) {
            return true;
        }
    }
    false
}